WITH e AS (SELECT *, ifNull(npc_name, '') AS name FROM npc_shops WHERE zone_id = {zone:Int64} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), p AS (SELECT name, kind, item_id, arraySlice(arrayReverseSort(t -> t.k, groupArray((v, k, seen))), 1, 10) AS prices, count() AS price_kinds FROM (SELECT name, kind, item_id, (price, nation, nation_rank, conquest_rank) AS v, sum(n) AS k, argMax((capture_id, ts_ms), last_ts) AS seen FROM e GROUP BY name, kind, item_id, v) GROUP BY name, kind, item_id), a AS (SELECT name, kind, item_id, sum(n) AS n, uniqExact(capture_id) AS captures, max(last_ts) AS last, argMax(capture_id, last_ts) AS last_capture, arraySlice(arrayReverseSort(t -> t.1, arrayFlatten(groupArray(arrayMap(s -> (s.ts_ms, s.stock, s.max, capture_id), stock)))), 1, 10) AS stocks FROM e GROUP BY name, kind, item_id) SELECT a.name AS npc_name, a.kind AS kind, a.item_id AS item, z.name AS item_name, a.n AS n, a.captures AS captures, a.last AS last, a.last_capture AS last_capture, a.stocks AS stock, p.prices AS prices, p.price_kinds AS price_kinds FROM a JOIN p USING (name, kind, item_id) LEFT JOIN (SELECT id, any(name) AS name FROM item_names WHERE id IN (SELECT item_id FROM e) GROUP BY id) z ON z.id = a.item_id ORDER BY npc_name, kind, item_name
